INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('‘Youth Rising’ in print', 'youth-rising-in-print', '<div></div>
<table cellspacing="0" cellpadding="0">
<tbody>
<tr>
<td><a href="https://2.bp.blogspot.com/-p1wXuLTLP5g/Tt5SjXrTEBI/AAAAAAAAAXk/ibP6L7F2guM/s1600/SpunOutMag.jpg"><img loading="lazy" decoding="async" src="https://2.bp.blogspot.com/-p1wXuLTLP5g/Tt5SjXrTEBI/AAAAAAAAAXk/ibP6L7F2guM/s400/SpunOutMag.jpg" width="326" height="400" border="0" /></a></td>
</tr>
<tr>
<td>Youth Rising</td>
</tr>
</tbody>
</table>
<p><span><a href="https://spunout.ie/">Spunout.ie</a> has published 20,000 copies of a new youth magazine called ‘Youth Rising’ and if your local youth group wants copies, they’re available for free.</span></p>
<div></div>
<div><span><span> </span></span><br />
<span>The magazine has already gone out to schools, colleges, youth centres, cinemas, cafes and other youth settings throughout the country.</span></div>
<div></div>
<div><span><span> </span> </span><br />
<span>‘Youth Rising’ features the voices of young people covering topics such as unemployment, sexual health, emigration, protest, politics, music and humor. </span></div>
<div><span> </span><br />
<span>It features a full directory of youth organisations and help services throughout the island of Ireland.</span></div>
<div><span><span> </span><br />
</span></div>
<div><span>To request bulk copies </span><span>email: <span><a href="mailto:info@spunout.ie">info@spunout.ie</a></span></span></div>', 'Youth Rising Spunout.ie has published 20,000 copies of a new youth magazine called ‘Youth Rising’ and if your local youth group wants copies, they’re available for free. The magazine has already gone out to schools, colleges, youth centres, cinemas, cafes and other youth settings throughout the country. ‘Youth Rising’ features the voices of', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 237, 1, '2011-12-06T17:39:00Z', '2019-10-15T16:20:46Z', '2011-12-06T17:39:00Z')
