INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Blue Drum – 10 Years', 'blue-drum-10-years', '<p>        </p>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-MjpVcM6vpEk/Tt42D91YNNI/AAAAAAAAAXU/tIp_y7lyORM/s1600/ISS+37-BLUE+DRUM+10+YEARS.JPG"><img loading="lazy" decoding="async" border="0" height="300" src="https://3.bp.blogspot.com/-MjpVcM6vpEk/Tt42D91YNNI/AAAAAAAAAXU/tIp_y7lyORM/s400/ISS+37-BLUE+DRUM+10+YEARS.JPG" width="400" /></a></td>
</tr>
<tr>
<td>10 years of Blue Drum</td>
</tr>
</tbody>
</table>
<p></p>
<div><span>Community arts organisation Blue Drum this year celebrates 10 years working with families and communities. Thousands of community workers have been trained in the arts and Blue Drum has developed a volunteer programme and an arts and health programme.</span></div>
<p><a name=''more''></a><o:p></o:p></p>
<div><span>“Gone are the days when art is put in its box as a tool, therapy or trophy,” said director Ed Carroll. “Our work continues to be ambitious and precarious.”&nbsp;</span><span>Traditionally, community arts work has been dogged by poor facilities, materials and skills – which made attracting the support of local arts organisations and offices vital.&nbsp;</span></div>
<div></div>
<div><span>Funded by the Family Support Agency and receiving €80,000 in funding, the organisation works with 107 Family Resource Centres (FRCs). Over the next decade Blue Drum sees its role as an advocate of artwork in and by communities, promoting local art practices and expressive life.<o:p></o:p></span></div>
<div></div>
<div><span>“A core part of our work will be to convince others about the public value of this work,” said Mr Carroll. The organisation is committed to promoting cultural rights.&nbsp;</span><span>Recently, Blue Drum, in&nbsp;response to thousands of requests, organised hundreds of artist workshop days for FRCs, to showcase the work of Travellers, children and women.</span></div>
<div></div>
<div><span>Like many other community projects, the organisation faces cutbacks.&nbsp;</span><span>“This work won’t just get cut-back but cut-out,” added Mr Carroll. “We need advocates who are loyal supporters of making more artwork happen in local communities.”</span></div>
<div></div>
<div><span><i>Blue Drum is registered as a charity and managed by five part-time project leaders and three volunteers.</i><o:p></o:p></span></div>
<p></p>', '10 years of Blue Drum Community arts organisation Blue Drum this year celebrates 10 years working with families and communities. Thousands of community workers have been trained in the arts and Blue Drum has developed a volunteer programme and an arts and health programme. “Gone are the days when art is put in its box', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 238, 1, '2011-12-06T15:39:00Z', '2011-12-06T15:39:00Z', '2011-12-06T15:39:00Z')
