INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('High five looking at alignment of local govt & local development sector', 'high-five-looking-at-alignment-of-local-govt-local-development-sector', '<div></div>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-poFBEUfLdZA/Tt49_qgbOlI/AAAAAAAAAXc/vOB8R632Usc/s1600/jim-miley.jpg"><img loading="lazy" decoding="async" border="0" height="266" src="https://4.bp.blogspot.com/-poFBEUfLdZA/Tt49_qgbOlI/AAAAAAAAAXc/vOB8R632Usc/s400/jim-miley.jpg" width="400" /></a></td>
</tr>
<tr>
<td>Jim Miley</td>
</tr>
</tbody>
</table>
<p><span>Five people were appointed by Minister Phil Hogan to a high level steering group in September to look&nbsp;at how a closer alignment between local government and the local development sector would work.</span></p>
<div></div>
<div><span lang="EN-IE">The five&nbsp;were chosen on the basis of their experience and considerable knowledge of both the Local Government and Local Development sectors,&nbsp;said the Department of the Environment, Community and Local Government. They are:</span><span><o:p></o:p></span></div>
<div></div>
<div><i><span lang="EN-IE"><b>Jim Miley </b>(pictured)</span></i><span lang="EN-IE">&nbsp;&#8211;&nbsp;former chairperson of Concern Worldwide, founder of&nbsp;<a href="https://myhome.ie/"><span>myhome.ie</span></a>&nbsp;and former secretary general of Fine Gael (in the late ‘90s). He was once a broadcaster and also served in the past as chief e</span><span>xecutive of Dublin City Chamber of Commerce</span><span lang="EN-IE">. Mr Miley will chair the steering group.</span><span><o:p></o:p></span></div>
<div></div>
<div><b><i><span lang="EN-IE">Geraldine Tallon</span></i></b><span lang="EN-IE">&nbsp;&#8211; secretary general of the Department of the Environment, Community&nbsp;and Local Government</span><span><o:p></o:p></span></div>
<div></div>
<div><b><i><span lang="EN-IE">Gerry Kearney</span></i></b><span lang="EN-IE">&nbsp;– former secretary general of the Department of Community, Rural and Gaeltacht Affairs&nbsp;</span><span><o:p></o:p></span></div>
<div></div>
<div><b><i><span lang="EN-IE">Dr. Patricia O’Hara</span></i></b><span lang="EN-IE">&nbsp;– regional policy expert with professorial duties at the National Institute for Regional Spatial Analysis in Maynooth</span><span><o:p></o:p></span></div>
<div></div>
<div><b><i><span lang="EN-IE">Liam Keane</span></i></b><span lang="EN-IE">&nbsp;&#8211; former regional co-ordinator&nbsp;of HSE South.</span><span><o:p></o:p></span></div>
<div></div>
<div><b><i><span lang="EN-IE">Martina Moloney</span></i></b><span lang="EN-IE">&nbsp;&#8211; Galway County Manager.</span></div>
<p><a name=''more''></a><span>It is anticipated the Steering Group will submit recommendations to the Minister by the end of January.</span></p>
<div></div>
<div><b><span lang="EN-IE">SUBMISSIONS INVITED</span></b><span><o:p></o:p></span></div>
<div></div>
<div><span lang="EN-IE">Interested parties have been invited to make submissions to the steering group and a&nbsp;number of presentations by key stakeholders have taken place. Questionnaires have also been issued to stakeholders including:</span><span><o:p></o:p></span></div>
<div></div>
<div><span lang="EN-IE">·</span><span lang="EN-IE">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span lang="EN-IE">&nbsp;&#8211;&nbsp;</span><span lang="EN-IE">local development companies and their representative organisation (namely the ILDN),</span><span><o:p></o:p></span></div>
<div><span lang="EN-IE">·</span><span lang="EN-IE">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span lang="EN-IE">&nbsp;&#8211;&nbsp;</span><span lang="EN-IE">County and city managers and their representative organisation (CCMA),</span><span><o:p></o:p></span></div>
<div><span lang="EN-IE">·</span><span lang="EN-IE">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span lang="EN-IE">&nbsp;&#8211;&nbsp;</span><span lang="EN-IE">the three representative organisations for the elected members;</span><span><o:p></o:p></span></div>
<div><span lang="EN-IE">·</span><span lang="EN-IE">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span lang="EN-IE">&nbsp;&#8211;&nbsp;</span><span lang="EN-IE">the network body for the Community and Voluntary Fora;</span><span><o:p></o:p></span></div>
<div><span lang="EN-IE">·</span><span lang="EN-IE">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span lang="EN-IE">&nbsp;&#8211;&nbsp;</span><span lang="EN-IE">Volunteer Ireland – the representative body for the 22 State-funded volunteer centres;</span><span><o:p></o:p></span></div>
<div><span lang="EN-IE">·</span><span lang="EN-IE">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span lang="EN-IE">&nbsp;&#8211;&nbsp;</span><span lang="EN-IE">the Wheel, Community Workers Co-operative, Social Justice Ireland as representative bodies for community and &#8211; &#8211; voluntary organisations; and</span><span><o:p></o:p></span></div>
<div><span lang="EN-IE">·</span><span lang="EN-IE">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span lang="EN-IE">&nbsp;&#8211;&nbsp;</span><span lang="EN-IE">Service users; by way of focus groups and questionnaires.</span><span><o:p></o:p></span></div>
<div></div>
<div><span lang="EN-IE">As part of the consultation process, the steering group is also accepting submissions from other parties as they come forward.&nbsp;</span><span><o:p></o:p></span></div>', 'Jim Miley Five people were appointed by Minister Phil Hogan to a high level steering group in September to look at how a closer alignment between local government and the local development sector would work. The five were chosen on the basis of their experience and considerable knowledge of both the Local Government and Local Development sectors, said', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 241, 1, '2011-12-06T12:35:00Z', '2011-12-06T12:35:00Z', '2011-12-06T12:35:00Z')
