INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('The other 1%', 'the-other-1', '<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-ZwZOPCXPsaI/Ttz2WTY8y2I/AAAAAAAAAWU/vFYae4imkA0/s1600/Bobbydamien.jpg"><img loading="lazy" decoding="async" border="0" height="306" src="https://4.bp.blogspot.com/-ZwZOPCXPsaI/Ttz2WTY8y2I/AAAAAAAAAWU/vFYae4imkA0/s400/Bobbydamien.jpg" width="400" /></a></td>
</tr>
<tr>
<td><span>Childcare worker Damien Walshe with Bobby Hogan and Jack Keely (credit Matt Kavanagh)</span></td>
</tr>
</tbody>
</table>
<div>
<div><span>&#8211; 99% of childcare workers are female</span><br /><span>By Conor Hogan</span><span></span><br /><span> </span><br /><span>It is strange that while completely normal for a man to take care of his own children, those who wish to make a career out of childcare are often greeted with suspicion. </span><br /><span></span><br /><span>“The question is sometimes asked &#8211; ‘Why would a man want to be in a room with children?’ – but the same would never be posed about a woman,” says Andrew Doherty of the Waterford County Childcare Community.</span><br /><span></span><br /><span>While this is one of the reasons for the low participation rate by men in childcare, it doesn’t quite explain the especially low rate in Ireland, estimated at less than 1% of staff – the worst in the EU. Compare this to the higher than 20% participation rate in Norway and Denmark.&nbsp;</span><br /><span></span><br /><span>So, is there any immediate difference between Ireland and these countries that could explain this disparity? </span><br /><a name=''more''></a><span>For starters, there is a generally different emphasis on what activities the children are involved in.&nbsp;</span><br /><span></span><br /><span>MEN IN CHILDCARE IN NORWAY</span><br /><span></span><br /><span>“In Norway,” said Mr Doherty, “children spend 60% of their </span><span>time outdoors doing activities such as fishing and gathering timber. These are the kind of things that would attract a man into that kind of a position. </span><br /><span></span><br /><span>&#8220;In Ireland, we spend a lot more time indoors. Another cause would be the poor paying conditions. There is a certain expectation on men here to be the breadwinners – that it’s okay for the woman to do it, if she is not the main wage-earner in the house.”</span><br /><span></span><br /><span>Damien Walshe is one of that rare breed of pre-school carers, though it wasn’t a job he originally planned on doing for a living. </span><br /><span></span><br /><span>PARENTS “A BIT SHOCKED”</span><br /><span></span><br /><span>“After I finished my Leaving Cert in ’07,” he told us, “I didn’t have the honours Irish, so I decided to do the B.A. in Early Childhood Studies in Waterford I.T. as an alternative way of getting into primary school teaching. I went out on placement in the Clonmel Community Resource Centre and discovered that early years really suited me.”</span><br /><span></span><br /><span>His experiences since he started have been positive; however the rarity of men working in the sector took some people a little aback: “My manager had never even come across another man who applied for the position before. The parents, as well, were initially a bit shocked. Once they got over that, though, they were very welcoming and supportive.”</span><br /><span></span><br /><span>Mr Walshe is now in the second year of an MA in Social Studies in WIT and his thesis is focussed on “the influence male role models can have on the children of lone parent families.” Ireland currently has the highest of single-parent families in the EU at 23%. </span><br /><span>Coupled with the lack of men in childcare, many children are growing up without a positive male role model.</span><br /><span></span><br /><span>Men In Childcare network</span><br /><span></span><br /><span>In 2004, the ‘Men In Childcare Network’ was established to support men working in crèches and Montessori, while raising awareness about the importance of increasing the number of men involved. They have also helped create a pan-European network of other male childcare workers across the EU. Their aim is to increase the male participation rate to 5% by the year 2020.</span><br /><span></span><br /><span>“We have to normalize the idea that men can be involved in Childcare,” Doherty said, “and what is very important is that we get the media interested in the topic”.</span><br /><span>On November 19</span><span>th</span><span>, the network held a conference in Dublin entitled ‘Reimagining Childhood Care and Education.’</span></p>
<p><span>The Men In Childcare network receives support from Pobal. </span><br /><span></span><br /><span>T: 087-2299208.</span><br /><span>E: <a href="mailto:menicirl@gmail.com">menicirl@gmail.com</a></span><br /><span>F: <a href="https://facebook.com/meninchildcare">facebook.com/meninchildcare</a></span></div>
</div>
<div></div>', 'Childcare worker Damien Walshe with Bobby Hogan and Jack Keely (credit Matt Kavanagh) – 99% of childcare workers are femaleBy Conor Hogan It is strange that while completely normal for a man to take care of his own children, those who wish to make a career out of childcare are often greeted with suspicion. “The', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 243, 1, '2011-12-05T16:53:00Z', '2011-12-05T16:53:00Z', '2011-12-05T16:53:00Z')
