INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Community safety: Parents found wanting', 'community-safety-parents-found-wanting', '<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-tdyC6Z6gl_M/TtzXbaT6QKI/AAAAAAAAAV0/p0yhpZE8VaY/s1600/ISS+37-Martin+Power+UL_0413.JPG"><img loading="lazy" decoding="async" border="0" height="200" src="https://3.bp.blogspot.com/-tdyC6Z6gl_M/TtzXbaT6QKI/AAAAAAAAAV0/p0yhpZE8VaY/s200/ISS+37-Martin+Power+UL_0413.JPG" width="160" /></a></td>
</tr>
<tr>
<td>Martin Power, UL</td>
</tr>
</tbody>
</table>
<p></p>
<div><span>UL Sociology Dept launched a report on November 4</span><span>th</span><span> that, if its recommendations were implemented, could make life a lot easier for people in communities plagued by anti-social behaviour.</span><br /><span></span><br /><span>“It’s a taboo topic, but everyone we spoke to mentioned children who were not being parented,” said Dr Cliona Barnes, co-author of the ‘Feeling Safe in Our Community’with Dr Martin Power.</span><br /><a name=''more''></a></div>
<div>
<div><span>“We didn’t anticipate the level of discussion about poor parenting from parents, all the residents’ groups, single parents, married parents, elderly parents, estate workers, all of the officals we spoke to. And this notion that the HSE should be responsible.</span><br /><span></span><br /><span>“Young people below the age of criminal responsibility are the main people responsible for unsafety. Not meaning to sensationalise it, or red-top it, but some people we spoke to are afraid of children, as young as four, because of who they might be related to.</span><br /><span></span><br /><span>“There’s a breakdown between the older generations and younger people. Older people are genuinely afraid of young people, it’s a big problem.</span><br /><span></span><br /><span>“So who is responsible when parents aren’t?”</span><br /><span></span><br /><span>The report is available in hard copy format through UL.</span></div>
</div>', 'Martin Power, UL UL Sociology Dept launched a report on November 4th that, if its recommendations were implemented, could make life a lot easier for people in communities plagued by anti-social behaviour.“It’s a taboo topic, but everyone we spoke to mentioned children who were not being parented,” said Dr Cliona Barnes, co-author of the ‘Feeling', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 245, 1, '2011-12-05T14:41:00Z', '2019-09-13T10:48:40Z', '2011-12-05T14:41:00Z')
