INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Take children outside!', 'take-children-outside', '<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-QJuab41jiNM/TtzVYOBgq6I/AAAAAAAAAVs/JgMNpzqsm9o/s1600/Take+kids+outdoors+guidebook.png"><img loading="lazy" decoding="async" border="0" height="320" src="https://4.bp.blogspot.com/-QJuab41jiNM/TtzVYOBgq6I/AAAAAAAAAVs/JgMNpzqsm9o/s320/Take+kids+outdoors+guidebook.png" width="223" /></a></td>
</tr>
<tr>
<td>Implementation Guide&nbsp;</td>
</tr>
</tbody>
</table>
<p></p>
<div><span>Play providers often say they need to strike a balance between the risks and the benefits of offering children challenging play opportunities. </span><span> </span><span>An easy to cut the risks down is to stay indoors, unhealthy though it may be in other ways.</span><br /><span></span><br /><span>In England, they’re trying to tackle this and the ‘Play Safety Forum’ with the backing of government departments responsible for children and education has produced a 128-page guidebook.</span><br /><span></span><br /><span>It’s called ‘Managing Risk In Play Provision: An Implementation Guide’ and Is free to download. Creche and childcare managers – in community and private settings here – may enjoy reading up on England’s approach while the turkey is in the oven this Christmas!</span><br /><span></span><br /><span>Download from: </span><span><a href="https://bit.ly/vglhbo">https://bit.ly/vglhbo</a></span></div>', 'Implementation Guide Play providers often say they need to strike a balance between the risks and the benefits of offering children challenging play opportunities. An easy to cut the risks down is to stay indoors, unhealthy though it may be in other ways.In England, they’re trying to tackle this and the ‘Play Safety Forum’ with', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 246, 1, '2011-12-05T14:32:00Z', '2019-09-13T10:48:49Z', '2011-12-05T14:32:00Z')
