INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Building breakthrough communities', 'building-breakthrough-communities', '<div><span></p>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://1.bp.blogspot.com/-CsINmA_7Zfw/TtzSpjU_5yI/AAAAAAAAAVk/JC-GOPJE_cA/s1600/ISS+37-New+Carnegie+Comm+Resilience+book.png"><img loading="lazy" decoding="async" border="0" height="320" src="https://1.bp.blogspot.com/-CsINmA_7Zfw/TtzSpjU_5yI/AAAAAAAAAVk/JC-GOPJE_cA/s320/ISS+37-New+Carnegie+Comm+Resilience+book.png" width="243" /></a></td>
</tr>
<tr>
<td>New Carnegie Resilience book</td>
</tr>
</tbody>
</table>
<div><span><span>Tuesday November 22</span><span>nd</span><span> saw a networking session for community people in Ireland interested in the concept of resilience, REPORTS GEAROID FITZGIBBON.</span></span></div>
<div><span> </span></div>
<div><span>The “Networking for Community Resilience” event was hosted by Davie Philip (<a href="https://cultivate.ie/">Cultivate.ie</a>) and Chris Chapman and supported by Carnegie UK Trust.</span></div>
<p></span></div>
<div><span><span></span><br /><span>Nick Wilding said Carnegie is backing Community Resilience by supporting the sharing of best practice in England, Ireland, Scotland, Wales via its online network (<a href="https://www.fieryspirits.com/">www.fieryspirits.com</a>). &nbsp;As Mr Wilding pointed out, the concept of building ‘Community Resilience’ is backed up by on-the-ground experience and academic research into social capital.</span><br /><span></span><br /><span>Carnegie recently sponsored a handbook called ‘Exploring Community Resilience’ which shares stories and promotes greater co-operation among community activists, professionals, funders and policy makers. </span><br /><span>Download from this link: <a href="https://bit.ly/vtF59L">https://bit.ly/vtF59L</a>. </span><br /><span></span><br /><span>Meanwhile, Deborah Frieze, of the Berkana Institute did a session on the importance of games and play in community work, giving examples from Brazil and Africa of how “community games” had been used to tackle intractable community problems, as detailed in her book ‘Walk Out Walk On’.</span></span></div>', 'New Carnegie Resilience book Tuesday November 22nd saw a networking session for community people in Ireland interested in the concept of resilience, REPORTS GEAROID FITZGIBBON. The “Networking for Community Resilience” event was hosted by Davie Philip (Cultivate.ie) and Chris Chapman and supported by Carnegie UK Trust. Nick Wilding said Carnegie is backing Community Resilience by', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 247, 1, '2011-12-05T14:25:00Z', '2019-09-13T10:48:56Z', '2011-12-05T14:25:00Z')
