INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('International community development conference', 'international-community-development-conference', '<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-yNLMbUrYWIU/TtzKZRP2gpI/AAAAAAAAAVc/EKBlsM_ZHoU/s1600/NUI+Maynooth.jpg"><img loading="lazy" decoding="async" border="0" height="282" src="https://3.bp.blogspot.com/-yNLMbUrYWIU/TtzKZRP2gpI/AAAAAAAAAVc/EKBlsM_ZHoU/s400/NUI+Maynooth.jpg" width="400" /></a></td>
</tr>
<tr>
<td>NUI Maynooth</td>
</tr>
</tbody>
</table>
<div></div>
<div>               </p>
<div><span>An international community development conference was held in Maynooth  on November 16</span><sup><span>th</span></sup><span> with speakers attending from Russia, Scotland, Australia, Holland, Liberia, Belgium and Ireland.<o:p></o:p></span></div>
<div><span><br /></span><span>Around 170 people took part and the event was oversubscribed.</span><span> </span><span>“It wasn’t all about programmes and structures for change,” said one participant, “but about taking time to think about the need for community development today to bring about social change.”</span></div>
<p><a name=''more''></a><o:p></o:p></p>
<div><span>Capitalism was widely criticised for the way it creates an underclass of people across the world.</span><span> </span><span>Dr Peter Westoby from Australia spoke about “going back” to really listen to communities and their real needs.</span><span><br /><br /></span><span><o:p></o:p></span></div>
<div><span>Rappateur for the day, Ann Irwin, commented afterwards saying people were asking if now was an opportunity for community development to reassert itself.</span><span> </span><span>“What struck me was the similarities the world over with community development being undervalued.”</span><span><br /><br /></span><span><o:p></o:p></span></div>
<div><span>She said Ireland was seen as “one of the frontrunners internationally in community development and participants from abroad were shocked at the changes in recent years here.”</span><span> </span><span>Ms Irwin said community development was now structurally part of local development and that the two were not the same.</span><span><br /><br /></span><span><o:p></o:p></span></div>
<div><span>The conference was organised by the Maynooth’s Department of Applied Social Studies, in association with the Community Workers Co-operative and the European Community Development Network.</span><span> </span><span>The conference was held in conjunction with celebrations to mark 30 years of community work, education and training at NUI Maynooth.</span><span><o:p></o:p></span></div>
<p></div>', 'NUI Maynooth An international community development conference was held in Maynooth on November 16th with speakers attending from Russia, Scotland, Australia, Holland, Liberia, Belgium and Ireland. Around 170 people took part and the event was oversubscribed. “It wasn’t all about programmes and structures for change,” said one participant, “but about taking time to think about', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 248, 1, '2011-12-05T13:54:00Z', '2011-12-05T13:54:00Z', '2011-12-05T13:54:00Z')
