INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Arklow: Men leave their shed in a boat', 'arklow-men-leave-their-shed-in-a-boat', '<div><b><span>BY ALAN JACQUES<o:p></o:p></span></b></div>
<div><b><span><br /></span></b></div>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-EmEVxP_bfmY/Ttyvu4Q8FDI/AAAAAAAAAUk/rzUfNdpWwJU/s1600/Arklow+Boat+Photos+1.JPG"><img loading="lazy" decoding="async" border="0" height="180" src="https://4.bp.blogspot.com/-EmEVxP_bfmY/Ttyvu4Q8FDI/AAAAAAAAAUk/rzUfNdpWwJU/s400/Arklow+Boat+Photos+1.JPG" width="400" /></a></td>
</tr>
<tr>
<td><span>An Bád Inbhear Mór</span></td>
</tr>
</tbody>
</table>
<div><span>The 25 members of Arklow Men’s Sheds Group made waves recently as they kept their hometown’s long and proud tradition of boat building alive with the launch of their 20ft timber dory.</span></div>
<div></div>
<div><span><br /></span></div>
<div><span>Named &#8216;An Bád Inbhear Mór&#8217;, the rowing boat took 13 weeks to build at a workshop in Croghan Industrial Estate with timber sourced from the ‘TSV Asgard II’ supply.</span></div>
<p><a name=''more''></a><span> <o:p></o:p></span></p>
<div><span>The Arklow Boat Project, captured the imagination of the entire community and 16 men from the local Men’s Sheds Group, ranging in age from 30 to 60, participated in the project. According to Katy Hughes of Arklow CDP, the project has played a huge role in getting the men’s group up and running in the community.</span></div>
<div><span><br /></span></div>
<div><span>“This project has brought about a great sense of hope and pride not only to the men involved, but to the whole town. The boat was paraded through the centre of the town with a pipe band on the day of its launch and there was a great buzz. There was such great excitement when it finally took to water and it did exactly what it was supposed to do,” said Ms Hughes.<o:p></o:p></span></div>
<div><span><br /></span></div>
<div><span>&#8216;An Bád Inbhear Mór&#8217; has since been donated to Arklow Sea Scouts. The Sheds group also continues to put their boat building skills to great use having built dinghies and canoes in recent weeks.<o:p></o:p></span></div>
<div><span><br /></span></div>
<div><span>The training involved was conducted under Goal 2 of the Local and Community Development Programme which seeks to increase access to formal and informal educational, recreational and cultural activities and resources.<o:p></o:p></span></div>
<div><span><br /></span></div>
<div><span>Ms Hughes told ‘Changing Ireland’ that many groups contributed to the success of the project including Arklow Pipe Band, Arklow Sea Scouts, Arklow Women’s Club, the Harbour Bar and other local businesses. <o:p></o:p></span></div>
<div><span><br /></span></div>
<div><span>Arklow has a long and proud tradition of boat building, most notably for building timber boats such as Francis Chichester’s ‘Gypsy Moth III’ and the ‘TSV Asgard II’ from which timber was sourced for the making of &#8216;An Bád Inbhear Mór&#8217;.<o:p></o:p></span></div>
<div><span><br /></span></div>
<div><span>The men’s boat project was coordinated by Arklow CDP which is part of County Wicklow Partnership and received funding from the Department of Social Protection and County Wicklow VEC Community Education.</span><o:p></o:p></div>', 'BY ALAN JACQUES An Bád Inbhear Mór The 25 members of Arklow Men’s Sheds Group made waves recently as they kept their hometown’s long and proud tradition of boat building alive with the launch of their 20ft timber dory. Named ‘An Bád Inbhear Mór’, the rowing boat took 13 weeks to build at a workshop', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 252, 1, '2011-12-05T11:52:00Z', '2011-12-05T11:52:00Z', '2011-12-05T11:52:00Z')
