INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('A €3.6 billion error? Here’s what we could do with that money', 'how-3-6-million-euro-could-be-better-spent', '<p>Ireland is €3.6 <strong><em>billion</em></strong> better off than we thought.</p>
<p>The Department of Finance <a href="https://www.rte.ie/news/2011/1101/finance.html" target="_blank" rel="noopener noreferrer">confirmed today</a> that an accounting error took place. Well, if we were to make use of those billions, it would be:</p>
<p>&#8211; the same as giving everyone in Ireland €800 in ‘luck money’ for Christmas.</p>
<p>&#8211; the same as giving 167,000 unemployed people jobs.</p>
<p>&#8211; the same as the amount originally earmarked for regeneration of Limerick’s disadvantaged estates.</p>
<p>It’s also the same, coincidentally, as the amount the EU and IMF say we must cut in this year’s budget.</p>
<p>It’s all rather curious.</p>
<p><a href="https://www.economist.com/blogs/schumpeter/2011/10/german-banks" target="_blank" rel="noopener noreferrer">German officials found €55 billion</a> that had gone unnoticed in another “error” last month.</p>
<p>Seriously, Horace McDermott, our fictitious good news correspondent predicted as much in the summer of 2010 when he wrote that officials found €22 million lying in a biscuit tin in Anglo Irish Bank.</p>
<p>Horace never imagined he should be thinking in billions. The incredible becomes reality!</p>
<p><em><a href="https://unsplash.com/photos/6tG_liBojOk" target="_blank" rel="noopener noreferrer">Main photo</a>: <a href="https://unsplash.com/@jbrinkhorst" target="_blank" rel="noopener noreferrer">Jonathan Brinkhorst</a>/<a href="http://unsplash.com" target="_blank" rel="noopener noreferrer">Unsplash</a></em></p>', 'It’s all rather curious. Ireland is €3.6 billion better off than we thought.', 'https://changingireland.ie/wp-content/uploads/2011/11/photo-1527155781285-a10fb8d2be02.jpeg', 'Pile of 2c coins', '[{"slug":"funding","title":"Funding"}]', '[{"slug":"budget","title":"budget"},{"slug":"department-of-finance","title":"Department of Finance"},{"slug":"disadvantaged-communities","title":"disadvantaged communities"},{"slug":"employment-supports","title":"employment supports"},{"slug":"humour","title":"humour"},{"slug":"money","title":"money"}]', '', 261, 1, '2011-11-01T17:25:00Z', '2019-10-16T13:24:23Z', '2011-11-01T17:25:00Z')
