INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Sean Gallagher may yet answer community development questions', 'sean-gallagher-may-yet-answer-community-development-questions', '<p><span>3pm&nbsp;</span></p>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://1.bp.blogspot.com/-E_f5aGJqmPw/TqlFZ5b0IcI/AAAAAAAAASk/w5foroB0pZA/s1600/Gallagher+community.jpg"><span><img loading="lazy" decoding="async" border="0" height="179" src="https://1.bp.blogspot.com/-E_f5aGJqmPw/TqlFZ5b0IcI/AAAAAAAAASk/w5foroB0pZA/s320/Gallagher+community.jpg" width="320" /></span></a></td>
</tr>
<tr>
<td><span>SEAN GALLAGHER AND (INSET) RITA FAGAN.</span></td>
</tr>
</tbody>
</table>
<p><span><span>UPDATE!</span></span><br /><span><span> We&#8217;ve just received a call from Sean Gallagher&#8217;s team. Kasia Murphy said Sean&#8217;s replies to our questions are on their way by email. She indicated that the candidate&#8217;s communications team has been stretched in recent days.</span></span><br /><span><span></span></span><br /><span><span> </span></span><br /><span>1pm</span><br /><span>FOR THE RECORD, on Monday of this week, &#8216;Changing Ireland&#8217; contacted Sean Gallagher’s press office to arrange an interview that we intended to publish online.&nbsp;</span><br /><span></span><br /><a name=''more''></a><span>We wanted to ask about his youth and community development background as they were topics he repeatedly championed throughout his campaign. We were politely informed that if we sent our questions by email, they would be answered promptly.&nbsp;</span><br /><span>The following day, we added a further question asking him to comment on Rita Fagan’s criticisms on TV3 of his lack of protestations at the closures of community projects in recent years.&nbsp;</span><br /><span>Throughout, we were assured that Sean would answer the questions before the end of the day. One day stretched into another and as of today, as the vote takes place, the questions remain unanswered.</span></p>', '3pm SEAN GALLAGHER AND (INSET) RITA FAGAN. UPDATE! We’ve just received a call from Sean Gallagher’s team. Kasia Murphy said Sean’s replies to our questions are on their way by email. She indicated that the candidate’s communications team has been stretched in recent days. 1pmFOR THE RECORD, on Monday of this week, ‘Changing Ireland’ contacted', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 263, 1, '2011-10-27T10:59:00Z', '2019-09-13T10:50:32Z', '2011-10-27T10:59:00Z')
