INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('PROFILE: Mike Redmond, Kilkenny Tús Supervisor', 'profile-mike-redmond-kilkenny-tus-supervisor', '<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://2.bp.blogspot.com/-J4t0GpUghGo/TlbVDRBaL5I/AAAAAAAAASc/ivDlLPyNPb8/s1600/Alan+Jacques+H%2526S.jpg"><img loading="lazy" decoding="async" border="0" height="200" src="https://2.bp.blogspot.com/-J4t0GpUghGo/TlbVDRBaL5I/AAAAAAAAASc/ivDlLPyNPb8/s200/Alan+Jacques+H%2526S.jpg" width="162" /></a></td>
</tr>
<tr>
<td>Alan Jacques</td>
</tr>
</tbody>
</table>
<div><b><span>Reporter ALAN JACQUES recently interviewed one of the 200 supervisors being hired this year to work with Local Development Companies on the <a href="https://www.citizensinformation.ie/en/employment/unemployment_and_redundancy/employment_support_schemes/tus.html">national&nbsp;Tús&nbsp;Scheme</a>:</span></b></div>
<div><span><br /></span></div>
<div>
<div><span><a href="https://www.cklp.ie/">County Kilkenny Leader Partnership</a> recently appointed Mike Redmond as the supervisor of its Tús scheme<b>.</b> <o:p></o:p></span></div>
<div><span>Mike has years of experience in the rail and construction recruitment industry here and in Britain. His main focus was to recruit, co-ordinate and manage operatives on some of the biggest British projects. <o:p></o:p></span></div>
<div>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-75L1afv4lGs/TlbVYBVnXCI/AAAAAAAAASg/iUImT-NUOrY/s1600/ISS+36-MikeRedmond.JPG"><img loading="lazy" decoding="async" border="0" height="264" src="https://3.bp.blogspot.com/-75L1afv4lGs/TlbVYBVnXCI/AAAAAAAAASg/iUImT-NUOrY/s320/ISS+36-MikeRedmond.JPG" width="320" /></a></td>
</tr>
<tr>
<td>Mike Redmond,&nbsp;<span>Tús&nbsp;Supervisor in Kilkenny</span></td>
</tr>
</tbody>
</table>
<p><span>Mike told ‘Changing Ireland’ he is now profiling candidates for the scheme and matching their skills for the areas in which participants are needed.</span></div>
<div><span>“We’ve been into the communities and spoken to the different organisations and groups to identify the participants that they require. We’ve had huge interest from around 70 different groups in the Kilkenny area and we will have no problem filling the 80 places on the Tús Scheme. We’ve interviewed 18 people in the Piltown area this week,” said Mike.</span><br /><a name=''more''></a><span><o:p></o:p></span></div>
<div><span>“The groups are looking for people in different areas, it’s a mixed bag really, everything from sporting coaches to green area workers. I’m getting stuck into it now and while we’re only getting up and running I’m sure it will be a great success,” he concluded.</span></div>
<div><span><b></b></span><br /><span><b>The Tús initiative is a community work placement scheme for unemployed people and County Kilkenny was allocated 80 places. Participants are identified by the Department of Social Protection and then referred by Kilkenny Leader Partnership.</b></span></div>
</div>
<div><b><span>You can read <a href="https://changingireland.blogspot.com/2011/08/penny-drops-for-3000-community-groups.html#more">earlier blog reports on&nbsp;</a></span></b><span><b><a href="https://www.blogger.com/goog_906520418">Tús</a></b></span><b><span>&nbsp;here, while our <a href="https://changingireland.ie/Issue36.pdf">Summer Edition of &#8216;Changing Ireland&#8217;</a> features 2 pages of reports on how the&nbsp;</span></b><b><span>Tús&nbsp;</span></b><b><span>Scheme is being rolled out nationwide.&nbsp;</span></b></div>', 'Alan Jacques Reporter ALAN JACQUES recently interviewed one of the 200 supervisors being hired this year to work with Local Development Companies on the national Tús Scheme: County Kilkenny Leader Partnership recently appointed Mike Redmond as the supervisor of its Tús scheme. Mike has years of experience in the rail and construction recruitment industry here and in', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 264, 1, '2011-08-25T23:07:00Z', '2011-08-25T23:07:00Z', '2011-08-25T23:07:00Z')
