INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Summer edition just PUBLISHED', 'summer-edition-just-published', '<p><a href="https://4.bp.blogspot.com/--0qftSrXD7U/TkvumDbxbLI/AAAAAAAAASU/FPZmvEiDolE/s1600/ISS+36+SCREENSHOT+COVER.png"><img loading="lazy" decoding="async" border="0" height="320" src="https://4.bp.blogspot.com/--0qftSrXD7U/TkvumDbxbLI/AAAAAAAAASU/FPZmvEiDolE/s320/ISS+36+SCREENSHOT+COVER.png" width="227" /></a><span>The <a href="https://changingireland.ie/Issue36.pdf">summer edition of &#8216;Changing Ireland</a>&#8216; &#8211; marking 10 years in operation &#8211; will be available online from lunchtime today and in print next week! The lead story is about Community Resilience &#8211; download the magazine from our homepage: <a href="https://changingireland.ie/">https://www.changingireland.ie</a>/</span><br /><span><br /></span><br /><a name=''more''></a><br /><span>This edition covers:</span></p>
<div>
<div></div>
<div><b><span>NEWS OF WORK ON THE GROUND<o:p></o:p></span></b></div>
<div><span lang="GA"><span>Mary Robinson, the Dalai Lama &amp; Rita Fagan<o:p></o:p></span></span></div>
<div><span>Bofin shows community work can be fun</span></div>
<div><span>Crumlin projects open doors to public<o:p></o:p></span></div>
<div><span>Theory &amp; practice ignored<o:p></o:p></span></div>
<div><span>Striking community workers</span></div>
<div><span>Limerick’s new one-stop shop for unemployed<o:p></o:p></span></div>
<div><span>Man in court over hatred charges<o:p></o:p></span></div>
<div><span>100 years of International Women’s Days<o:p></o:p></span></div>
<div><span>World Cup in Cavan<o:p></o:p></span></div>
<div><span>IN BRIEF: €2m for Travellers; Westmeath coverage; Galway tops for community development</span></div>
<div><span>Clondalkin helps asylum-seekers challenge deportation<o:p></o:p></span></div>
<div><span>Cork Travellers celebrate on the double<o:p></o:p></span></div>
<div></div>
<div><b><span>COMMUNITY SECTOR NEWS<o:p></o:p></span></b></div>
<div><span>Dublin jobs conference takes unusual approach<o:p></o:p></span></div>
<div><span lang="GA"><span>Galway: ‘Community Centre’ for sale <o:p></o:p></span></span></div>
<div><span><b><o:p>&nbsp;</o:p></b>&nbsp;</span></div>
<div><b><span>INTERVIEW: Minister PHIL HOGAN</span></b></div>
<div><b><span><br /></span></b></div>
<div><span><b>SURPRISING INTEREST IN </b><b>TÚS </b><b><o:p></o:p></b></span></div>
<div><span>3,000 groups apply, 1,200 people recruited<o:p></o:p></span></div>
<div><span>Tús uptake in Dublin, Mayo and Kilkenny<o:p></o:p></span></div>
<div></div>
<div><b><span>INTERGENERATIONAL WORK IN DUBLIN &amp; CORK</span></b></div>
<div></div>
<div><b><span>ART &amp; COMMUNITY WORK IN CORK<o:p></o:p></span></b></div>
<div></div>
<div><b><span>COMMUNITY &amp; VOLUNTARY NEWS<o:p></o:p></span></b></div>
<div><span>Facing up to unfair salary differences<o:p></o:p></span></div>
<div><span>Mayor says work “bull” at Citizens Forum<o:p></o:p></span></div>
<div></div>
<div><b><span>21 COMMUNITY SECTOR / PROGRAMME UPDATE<o:p></o:p></span></b></div>
<div><span>63 bodies approved out of 149 hopefuls<o:p></o:p></span></div>
<div><span lang="GA"><span>IMPACT highlights 20% cuts<o:p></o:p></span></span></div>
<div><span lang="GA"><span><br /></span></span></div>
<div><span><span lang="GA"></span></span></div>
<div><b><span>NATIONAL PROGRAMME TARGETS 2011<o:p></o:p></span></b></div>
<div><span>Jobs challenge being met, says Network<o:p></o:p></span></div>
<div><span></span></div>
<div><span>Island projects seek some independence</span></div>
<div><span>Programme takes shape<span lang="GA"><o:p></o:p></span></span></div>
<div></div>
<div><b><span>CONTROL OF HORSES ACT, 15 YEARS ON – PART 1<o:p></o:p></span></b></div>
<div><span>In focus: Cherry Orchard Equine Centre<o:p></o:p></span></div>
<div></div>
<div><b><span>HORACE, OUR GOOD NEWS CORRESPONDENT<o:p></o:p></span></b></div>
<div></div>
<div><b><span>COMMUNITY WORK ON FILM<o:p></o:p></span></b></div>
<div><span>Monaghan produces community work DVD<o:p></o:p></span></div>
<div><span>Community DVDs – Do’s and Don’ts!<o:p></o:p></span></div>
<div></div>
<div><b><span>RESOURCES: MAPPING COMMUNITIES<o:p></o:p></span></b></div>
<div><span>Social inclusion mapping now a reality<o:p></o:p></span></div>
<div><span>How to use Pobal Maps<o:p></o:p></span></div>
<div></div>
<div><b><span>LETTERS<o:p></o:p></span></b></div>
<div><span><span lang="EN-IE">Tús </span>coverage disappoints<o:p></o:p></span></div>
<div><span>Happy birthday CWC!<o:p></o:p></span></div>
<div><span>Volunteers needed</span></div>
<div><span><br /></span></div>
<div><b><span>MEN MATTER</span></b></div>
<div><span></span></div>
<div><span>A father’s story from the heart</span></div>
<div><span><br /></span></div>
<p></div>
<p><b><u><span lang="GA"><br clear="ALL" /> </span></u></b></p>', 'The summer edition of ‘Changing Ireland‘ – marking 10 years in operation – will be available online from lunchtime today and in print next week! The lead story is about Community Resilience – download the magazine from our homepage: https://www.changingireland.ie/This edition covers: NEWS OF WORK ON THE GROUND Mary Robinson, the Dalai Lama & Rita', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 266, 1, '2011-08-15T11:42:00Z', '2011-08-15T11:42:00Z', '2011-08-15T11:42:00Z')
