INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Island projects seek some independence', 'island-projects-seek-some-independence', '<p><span>English-speaking islands are moving closer to an agreement on a management structure for crucial projects funded through the Local and Community Development Programme.&nbsp;</span></p>
<div><span>Negotiations are continuing with the Department of Environment, Community and Local Government on how best to manage the staff and work of five Community Development Projects.<o:p></o:p></span></div>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://2.bp.blogspot.com/-hXcgjIggXNk/TkKvpFMTeBI/AAAAAAAAASI/rId8p27V_qA/s1600/Inishbofin+May+%252708+BEST+%2527ISLANDS%2527.JPG"><img loading="lazy" decoding="async" border="0" height="240" src="https://2.bp.blogspot.com/-hXcgjIggXNk/TkKvpFMTeBI/AAAAAAAAASI/rId8p27V_qA/s320/Inishbofin+May+%252708+BEST+%2527ISLANDS%2527.JPG" width="320" /></a></td>
</tr>
<tr>
<td>Photo by &#8216;Changing Ireland&#8217;: the ferry to Inishbofin.</td>
</tr>
</tbody>
</table>
<div><span>The five projects concerned are on Clare Island and Inishturk in Co. Mayo, Inishbofin in Co. Galway and Bere and Sherkin islands in Co. Cork which also provide support to the smaller Dursey, Whiddy, Long and Heir islands.<o:p></o:p></span></div>
<div><span>“We wanted to stay independent if we could, but that wasn’t a runner,” said Bere Island CDP co-ordinator John Walsh.</span></div>
<p><a name=''more''></a><o:p></o:p></p>
<div><span>The proposal being currently looked at by the Department, said John, would see two companies manage the island projects, one dealing with with Cork, the other with Mayo and Galway.<o:p></o:p></span></div>
<div><span>The chairperson of the Federation of Irish Islands, Padraic O’Malley, stressed in June that islands needed an unique and innovative inter-departmental and local authority approach to the rationalisation and integration of CDPs, farm schemes, fire-fighting, primary school education and healthcare.<o:p></o:p></span></div>', 'English-speaking islands are moving closer to an agreement on a management structure for crucial projects funded through the Local and Community Development Programme. Negotiations are continuing with the Department of Environment, Community and Local Government on how best to manage the staff and work of five Community Development Projects. Photo by ‘Changing Ireland’: the ferry', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 268, 1, '2011-08-10T16:21:00Z', '2011-08-10T16:21:00Z', '2011-08-10T16:21:00Z')
