INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Community centre for sale in Galway', 'community-centre-for-sale-in-galway', '<p><i><span><span lang="GA"><span><b>The summer edition of &#8216;Changing Ireland&#8217;</b>&nbsp;is about to be published. The magazine will be available through Eason outlets, by post to subscribers (free) and <a href="https://changingireland.ie/">on our website homepage</a>.&nbsp;</span></span><span>Here&#8217;s one of the more eye-catching stories that feature.</span></span></i></p>
<div><i><span><span><br /></span></span></i></div>
<div><span lang="GA"><span>A community centre and sports hall is up for sale, possibly the first to go under the hammer since the recession struck.<o:p></o:p></span></span></div>
<div><span lang="GA"><span>Mervue Community Centre in Galway is on the market and four potential buyers were “in talks” about buying the property as ‘Changing Ireland’ went to press.<o:p></o:p></span></span></div>
<div><a href="https://2.bp.blogspot.com/-gT2t4BTedeY/TjdCW0ZcO-I/AAAAAAAAAR8/goKYFYel8OE/s1600/Community+centres+%2528Mervue%2529+FOR+SALE.jpg"><img loading="lazy" decoding="async" border="0" height="237" src="https://2.bp.blogspot.com/-gT2t4BTedeY/TjdCW0ZcO-I/AAAAAAAAAR8/goKYFYel8OE/s320/Community+centres+%2528Mervue%2529+FOR+SALE.jpg" width="320" /></a></div>
<div><span>One of the trustees, parish priest Fr. Willie Cummins, said it was really a sports hall even though it was called a community centre.</span></div>
<div><span lang="GA"><span>The centre was built in the 1980s and is used by a local women’s club and an active retirement assocation. Fr. Cummins said that after the hall was built, the local soccer club and GAA developed their own facilities.<o:p></o:p></span></span></div>
<div><span lang="GA"><span>Three main factors have pushed the trustees to this point – high insurance costs, income-decline due to loss of tenants and a mounting list of costly repairs.<o:p></o:p></span></span></div>
<div><span lang="GA"><span></span></span><br /><a name=''more''></a><span lang="GA"><span>Now, the exterior and interior of the building has deteriorated in recent years and repairs could cost “up to €150,000”. <o:p></o:p></span></span></div>
<div><span>However, Fr. Cummins<span lang="GA"> stressed </span>that the centre will<span lang="GA"> not</span> change hands <span lang="GA">without</span> consultation with, and the agreement of, the local community in Mervue<span lang="GA">.<br />He also confirmed that any organisation that has used the centre regularly, will be able to continue doing so, even if the property is sold.<o:p></o:p></span></span></div>
<div><span lang="GA"><span>“That’ll be written into the agreement,” said Fr. Cummins, adding that he was now “very hopeful” it will sell.<o:p></o:p></span></span></div>
<div><span lang="GA"><span>He was unaware of any other community centres or local sports halls for sale in the country.<o:p></o:p></span></span></div>
<div><span lang="GA"><span>Mervue had a population of 2,130 in the last census and a third of Mervue residents are aged over-55.<o:p></o:p></span></span></div>
<div><span lang="GA"><span>The LCDP is active in Mervue and Ballybane and provides a wide range of community services.</span><span><o:p></o:p></span></span></div>', 'The summer edition of ‘Changing Ireland’ is about to be published. The magazine will be available through Eason outlets, by post to subscribers (free) and on our website homepage. Here’s one of the more eye-catching stories that feature. A community centre and sports hall is up for sale, possibly the first to go under the hammer since', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 271, 1, '2011-08-02T00:21:00Z', '2011-08-02T00:21:00Z', '2011-08-02T00:21:00Z')
