INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Pobal to continue, despite pre-election talk of closure', 'pobal-to-continue-despite-pre-election-talk-of-closure', '<div>
<div><a href="https://1.bp.blogspot.com/-X43zVU0jnt0/TjabMbbehbI/AAAAAAAAAR0/habIv8wZdG0/s1600/POBAL+LOGO.jpg"><span><img loading="lazy" decoding="async" border="0" height="132" src="https://1.bp.blogspot.com/-X43zVU0jnt0/TjabMbbehbI/AAAAAAAAAR0/habIv8wZdG0/s320/POBAL+LOGO.jpg" width="320" /></span></a></div>
<div><b><span>Pobal looks likely to continue to be supported by the Government, despite pre-election talk of closure, Minister Phil Hogan has indicated to &#8216;Changing Ireland&#8217;.</span></b></div>
</div>
<div>
<div><b><span>The Government agency was listed as one of the 145 so-called &#8220;quangos&#8221; that the State could do without, with Fine Gael proposing the takeover of its functions by local authorities. The body handled €377m of national and EU funding in 2007 and is responsible for managing a range of community-related Government programmes.</span></b></div>
</div>
<div>
<div><span><b>Recently, &#8216;Changing Ireland&#8217; asked Minister Phil Hogan about Pobal&#8217;s future.</b><span><o:p></o:p></span></span></div>
</div>
<div>
<div><span>Minister Hogan pointed out that it was a matter for Government and not for he alone to decide:<o:p></o:p></span></div>
</div>
<div>
<div><span><span>“While it is possible that the services provided by Pobal could be provided internally by my Department or other Departments,</span><span> it is unlikely that significant savings would arise given that staff resources would need to be redeployed, systems would require development and the necessary expertise in providing advice to the sectors concerned may not be readily available.&nbsp;</span><o:p></o:p></span></div>
</div>
<div>
<div><span>“Additionally, because Pobal delivers funding on behalf of a number of Departments involved in supporting services in the not-for-profit, community and voluntary sectors, the Company is in a unique position to bring considerable value-added because of its comprehensive knowledge of the sectors.&nbsp; The central administration and integration of services offered by the Company across the various programmes and the fact that the same staff work on a number of programmes are considerable strengths which would not be easily replicated if Departments separately implemented programmes.”</span></div>
<p><span>                  </span></p>
<div>
<div><span><b>&#8216;Changing Ireland&#8217; also asked about €750,000 which was recently cut from Pobal’s budget to manage the Dormant Accounts Fund. We asked was this re-distributed to community initiatives or sent to ‘Brussels’?</b><span><o:p></o:p></span></span></div>
</div>
<p><span>  </span></p>
<div>
<div><span>The Minister replied that “efficiency are retained as savings (and) are not redistributed.”</span><span><o:p></o:p></span></div>
</div>
</div>', 'Pobal looks likely to continue to be supported by the Government, despite pre-election talk of closure, Minister Phil Hogan has indicated to ‘Changing Ireland’. The Government agency was listed as one of the 145 so-called “quangos” that the State could do without, with Fine Gael proposing the takeover of its functions by local authorities. The', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 273, 1, '2011-08-01T11:51:00Z', '2011-08-01T11:51:00Z', '2011-08-01T11:51:00Z')
