INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Community development in Dublin 12', 'community-development-in-dublin-12', '<div><a href="https://1.bp.blogspot.com/-VWDEg8PjSxU/TiMFEIyIuWI/AAAAAAAAARs/zWvEJLjBSSk/s1600/SFP+Graduation+25.jpg"><img loading="lazy" decoding="async" border="0" height="271" src="https://1.bp.blogspot.com/-VWDEg8PjSxU/TiMFEIyIuWI/AAAAAAAAARs/zWvEJLjBSSk/s400/SFP+Graduation+25.jpg" width="400" /></a></div>
<p><span>Keep an eye on what&#8217;s happening through the Programme in Dublin 12 via <a href="https://www.blogger.com/goog_1908212542">this blog from community workers with </a></span><span><a href="https://d12lcdp.blogspot.com/">Rathmines Pembroke Community Partnership</a></span><span>. The photo is taken from coverage on the blog about a &#8216;Strengthening Families Programme&#8217;, an&nbsp;</span><span><span>internationally recognised parenting and family strengthening program for families.&nbsp;</span></span></p>', 'Keep an eye on what’s happening through the Programme in Dublin 12 via this blog from community workers with Rathmines Pembroke Community Partnership. The photo is taken from coverage on the blog about a ‘Strengthening Families Programme’, an internationally recognised parenting and family strengthening program for families.', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 275, 1, '2011-07-17T15:48:00Z', '2011-07-17T15:48:00Z', '2011-07-17T15:48:00Z')
