INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('We’ve mapped 120+ projects in the LCDP', 'weve-mapped-120-projects-in-the-lcdp', '<p>&#8216;Changing Ireland&#8217; has mapped over 120 projects in the Local and Community Development Programme.<br />We&#8217;ve pinpointed 95% of the locations to within metres and you can access the project/companies&#8217; email, phone and website details through the map.<br /><a href="https://batchgeo.com/map/6f3fc6f94693b38a499dbafea6ecbe96"><b>CLICK HERE TO SEE THE MAP AND ZOOM IN</b>.&nbsp;</a>You can click on a location for full details.</p>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-bp4MNMOZICw/Th2gq1BvOmI/AAAAAAAAARo/LTjISgLcd4E/s1600/Picture+9.png"><img loading="lazy" decoding="async" border="0" height="640" src="https://3.bp.blogspot.com/-bp4MNMOZICw/Th2gq1BvOmI/AAAAAAAAARo/LTjISgLcd4E/s640/Picture+9.png" width="491" /></a></td>
</tr>
<tr>
<td>A screenshot of the LCDP map by &#8216;Changing Ireland&#8217;</td>
</tr>
</tbody>
</table>
<p>Viewers can see all the projects together OR choose to only view (a) Local Development Companies, (b) projects on islands, for women and for Travellers, (c) Projects that provide specialist or national expertise, (d) Community Development Projects that operate under new alternative arrangements.<br />The Department&#8217;s and Pobal&#8217;s locations are also&nbsp;mapped as are projects that receive Programme funding yet do not fit neatly under any label for now.</p>', '‘Changing Ireland’ has mapped over 120 projects in the Local and Community Development Programme.We’ve pinpointed 95% of the locations to within metres and you can access the project/companies’ email, phone and website details through the map.CLICK HERE TO SEE THE MAP AND ZOOM IN. You can click on a location for full details. A screenshot of', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 276, 1, '2011-07-13T13:39:00Z', '2011-07-13T13:39:00Z', '2011-07-13T13:39:00Z')
