INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Limerick leads way with integrated service', 'limerick-leads-way-with-integrated-service', '<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-LqIyXqkURVE/Tg25sWU6qLI/AAAAAAAAARk/Mvl35bKQWTk/s1600/LES+Moyross+launch.JPG"><img loading="lazy" decoding="async" border="0" height="239" src="https://3.bp.blogspot.com/-LqIyXqkURVE/Tg25sWU6qLI/AAAAAAAAARk/Mvl35bKQWTk/s320/LES+Moyross+launch.JPG" width="320" /></a></td>
</tr>
<tr>
<td>Minister Joan Burton outside the new integrated office</td>
</tr>
</tbody>
</table>
<div><span lang="EN-IE"><span>Today, the Minister for Social Protection Joan Burton officially opened the new premises of Northside Local Employment Service at Watch House Cross, Moyross, Limerick.</span></span></div>
<div><span lang="EN-IE"><span>“This approach very much fits with my Department’s policy of integration of services,” said the Minister,” adding that she was struck by the “enthusiastic and imaginative way Limerick LES” delivers their service.</span></span></div>
<div><span lang="EN-IE"><span>The new office offers information and advice, job mediation, career guidance and job placement.</span></span></div>
<div><span lang="EN-IE"><span>The premises are a result of the merging of two full time Outreach Offices of the Local Employment Service (LES) which were located in Moyross and St. Munchin’s Community Centres.&nbsp; </span></span></div>
<div><span lang="EN-IE"><span>“I recall planning meetings when we said that we’ll meet clients on the beach in Ballybunion if need be,” said Sexton Cahill of the PAUL Partnership.</span></span></div>
<div><span lang="EN-IE"><span>The new location is beside a bookies and at the entrance to Moyross, at the Watch House Cross Shopping Centre. </span></span></div>
<div><span lang="EN-IE"><span>Local people are saying the location couldn’t have been better chosen.</span></span></div>
<div><span>This blog posting will be updated with further details, including web links, later.</span></div>', 'Minister Joan Burton outside the new integrated office Today, the Minister for Social Protection Joan Burton officially opened the new premises of Northside Local Employment Service at Watch House Cross, Moyross, Limerick. “This approach very much fits with my Department’s policy of integration of services,” said the Minister,” adding that she was struck by the', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 277, 1, '2011-07-01T12:13:00Z', '2011-07-01T12:13:00Z', '2011-07-01T12:13:00Z')
