INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('ISLANDS GET ASSURANCES; CWC GETS FUNDING CUT', 'islands-get-assurances-cwc-gets-funding-cut', '<p>Communities on Ireland&#8217;s offshore islands got a boost in recent days with the new Gaeltacht Minister Dinny McGinley assuring islanders the Government would continue to support their development.</p>
<div><span lang="EN-GB">He was speaking at the <a href="https://www.oileain.ie/">Cómdháil Oileáin na hÉireann (Federation of Irish Islands)</a> agm, held on Clare Island. The Irish Times reported: &#8220;Noting that access and infrastructural issues had been addressed, he said the next focus for sustainable development was the creation of enterprise and employment.&#8221;</span></div>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://1.bp.blogspot.com/-xq6_p2VPtMA/TfX7noGuSvI/AAAAAAAAARY/YuMO_jWh9Zk/s1600/ClareIslandByAllen.jpg"><img loading="lazy" decoding="async" border="0" height="277" src="https://1.bp.blogspot.com/-xq6_p2VPtMA/TfX7noGuSvI/AAAAAAAAARY/YuMO_jWh9Zk/s400/ClareIslandByAllen.jpg" width="400" /></a></td>
</tr>
<tr>
<td>Photo by A Meagher: Clare Island as seen from the Newport-Mulranny side.</td>
</tr>
</tbody>
</table>
<div><span lang="EN-GB">&#8220;He conceded that while islands had benefited from the fruits of the Celtic Tiger, there was no longer funding available for major expansion. However, the maintenance of such services as childcare, healthcare and waste management would be continued.&#8221;</span></div>
<div><span lang="EN-GB">Read the <a href="https://www.irishtimes.com/newspaper/ireland/2011/0613/1224298810962.html">full Irish Times news report here.</a></span></div>
<div><span lang="EN-GB">Approx. 2,944 islanders live on our offshore islands.</span></div>
<div></div>
<div><a href="https://3.bp.blogspot.com/-B7q2ORIQOUk/TfX7_hGieRI/AAAAAAAAARc/RVOwPN6B89s/s1600/CWC+LOGO.png"><img loading="lazy" decoding="async" border="0" height="118" src="https://3.bp.blogspot.com/-B7q2ORIQOUk/TfX7_hGieRI/AAAAAAAAARc/RVOwPN6B89s/s200/CWC+LOGO.png" width="200" /></a></div>
<div><b>CWC FUNDING</b></div>
<div><span lang="EN-GB">Meanwhile, the <a href="https://www.cwc.ie/">Community Workers Co-o</a>p has suffered a blow with news that funding it receives under the Scheme to Support National Organisations in the Community &amp; Voluntary Sector will not be continued.</span></div>
<div><span lang="EN-GB">The CWC can appeal the decision and met last Friday to consider options.</span></div>', 'Communities on Ireland’s offshore islands got a boost in recent days with the new Gaeltacht Minister Dinny McGinley assuring islanders the Government would continue to support their development. He was speaking at the Cómdháil Oileáin na hÉireann (Federation of Irish Islands) agm, held on Clare Island. The Irish Times reported: “Noting that access and infrastructural', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 278, 1, '2011-06-13T12:05:00Z', '2011-06-13T12:05:00Z', '2011-06-13T12:05:00Z')
